from rsa.common import bit_size


def get_integer_bit_size(num: int) -> int:
    """Calculate the number of bits needed to represent an integer. num: Integer value. If num is 0, returns 0. Only the absolute value of the number is considered."""
    try:
        return bit_size(num)
