from rsa.common import extended_gcd


def extended_euclidean_algorithm(a: int, b: int) -> typing.Tuple[int, int, int]:
    """Returns a tuple (r, i, j) such that r = gcd(a, b) = ia + jb. Example: extended_euclidean_algorithm(30, 18) -> (6, -1, 2)"""
