def decrypt_integer(cyphertext: int, dkey: int, n: int) -> int:
    """Decrypts a cypher text using the decryption key 'dkey', working modulo n. cyphertext: The encrypted integer to decrypt, dkey: The RSA private decryption exponent, n: The RSA modulus, e.g. decrypt_integer(123, 456, 789) -> 678."""
    try:
        return pow(cyphertext, dkey, n)
    except TypeError:
        raise ValueError("All parameters must be integers")
