def encrypt_integer(message: int, ekey: int, n: int) -> int:
    """Encrypts a message using encryption key 'ekey', working modulo n. message: The integer message to encrypt, ekey: The RSA encryption key, n: The modulus for RSA encryption. Example: encrypt_integer(123, 5, 1000) -> 827"""
    from rsa.core import encrypt_int

    try:
        return encrypt_int(message, ekey, n)
    except AssertionError as e:
        raise ValueError("Invalid input parameters") from e
    except ValueError as e:
        raise ValueError(str(e)) from e
    except OverflowError as e:
        raise OverflowError(str(e)) from e
```

